  'Use this code to connect a new computer or update one you have already saved.':
    'Χρησιμοποιήστε αυτόν τον κωδικό για να συνδέσετε έναν νέο υπολογιστή ή να ενημερώσετε έναν που έχετε ήδη αποθηκεύσει.',
