    'Ενημέρωση {value0}. Σύζευξη μόνο με τον ίδιο υπολογιστή.',
  'Choose a different computer': 'Επιλέξτε διαφορετικό υπολογιστή',
  'Long-press Dovo’s app icon and choose Start a task to select a server, project and favorite agent.':
    'Πατήστε παρατεταμένα το εικονίδιο της εφαρμογής Dovo και επιλέξτε Έναρξη εργασίας για να επιλέξετε διακομιστή, έργο και αγαπημένο πράκτορα.',
  'Open task launcher': 'Ανοίξτε το πρόγραμμα εκκίνησης εργασιών',
  'In Apple Shortcuts, add an Open URLs action with the link below. You can assign it to Siri, your Home Screen or Action button.':
    'Στις Συντομεύσεις της Apple, προσθέστε μια ενέργεια Άνοιγμα διευθύνσεων URL με τον παρακάτω σύνδεσμο. Μπορείτε να το αντιστοιχίσετε στο Siri, στην Αρχική οθόνη ή στο κουμπί Δράσης.',
  'Supported Android launchers also let you drag the Start a task shortcut onto your Home Screen.':
    'Τα υποστηριζόμενα προγράμματα εκκίνησης Android σάς επιτρέπουν επίσης να σύρετε τη συντόμευση Έναρξη μιας εργασίας στην Αρχική οθόνη σας.',
  'dovo://launch': 'dovo://launch',
  'In Shortcuts: Ask for Input → URL Encode → Text with the URL below → Open URLs. Review the draft, model and checkout before sending its first message.':
    'Στις Συντομεύσεις: Ζητήστε εισαγωγή → Κωδικοποίηση URL → Κείμενο με την παρακάτω διεύθυνση URL → Άνοιγμα διευθύνσεων URL. Ελέγξτε το προσχέδιο, το μοντέλο και το ταμείο πριν στείλετε το πρώτο του μήνυμα.',
