  'Optional URL fields: title, repositoryId, agentId. Requests wait on this phone while offline.':
    'Προαιρετικά πεδία URL: title, repositoryId, agentId. Τα αιτήματα περιμένουν σε αυτό το τηλέφωνο ενώ είστε εκτός σύνδεσης.',
