  'Forgetting removes this connection from your phone. Work on the computer continues.':
    'Η λήθη αφαιρεί αυτήν τη σύνδεση από το τηλέφωνό σας. Η εργασία στον υπολογιστή συνεχίζεται.',
  'Forget computer': 'Ξεχάστε τον υπολογιστή',
  'Forget {value0}?': 'Ξεχάστε το {value0};',
  'This phone’s access is removed from the computer too. Connecting again needs a new pairing code. Work on the computer continues.':
    'Η πρόσβαση αυτού του τηλεφώνου καταργείται επίσης από τον υπολογιστή. Για να συνδεθείτε ξανά, απαιτείται νέος κωδικός σύζευξης. Η εργασία στον υπολογιστή συνεχίζεται.',
  Forget: 'Ξεχάστε',
  'Conflicting edits are saved here while the runtime value stays in use. Select and copy an edit to recover it.':
    'Οι επεξεργασίες σε διένεξη αποθηκεύονται εδώ ενώ η τιμή χρόνου εκτέλεσης παραμένει σε χρήση. Επιλέξτε και αντιγράψτε μια επεξεργασία για να την ανακτήσετε.',
  'No recovered edits.': 'Δεν υπάρχουν ανακτημένες αλλαγές.',
  'Load older edits': 'Φόρτωση παλαιότερων επεξεργασιών',
  'Saved on {value0}. Discover and control simulators and connected phones on other paired computers over SSH.':
    'Αποθηκεύτηκε στο {value0}. Ανακαλύψτε και ελέγξτε προσομοιωτές και συνδεδεμένα τηλέφωνα σε άλλους αντιστοιχισμένους υπολογιστές μέσω SSH.',
  'the current runtime': 'το τρέχον περιβάλλον εκτέλεσης',
  'This computer is offline. Reconnect to load or save device hosts. Your draft is kept here.':
    'Αυτός ο υπολογιστής είναι εκτός σύνδεσης. Επανασυνδεθείτε για να φορτώσετε ή να αποθηκεύσετε κεντρικούς υπολογιστές συσκευών. Το πρόχειρό σας διατηρείται εδώ.',
  'Loading device hosts…': 'Φόρτωση κεντρικών υπολογιστών συσκευής…',
  'Retry device host settings': 'Δοκιμάστε ξανά τις ρυθμίσεις κεντρικού υπολογιστή της συσκευής',
  'Device Hub': 'Διανομέας συσκευής',
  'Enable device discovery and controls on this runtime. Turning it off keeps saved hosts and leaves devices running.':
    'Ενεργοποιήστε τον εντοπισμό συσκευής και τα στοιχεία ελέγχου σε αυτόν τον χρόνο εκτέλεσης. Η απενεργοποίησή του διατηρεί τους αποθηκευμένους κεντρικούς υπολογιστές και αφήνει τις συσκευές σε λειτουργία.',
  'Enable Device Hub': 'Ενεργοποίηση Device Hub',
  'Remote device hosts': 'Απομακρυσμένοι οικοδεσπότες συσκευών',
  'The destination requires an updated installed Dovo runtime and an existing pairing. SSH alone does not grant Dovo access.':
    'Ο προορισμός απαιτεί έναν ενημερωμένο εγκατεστημένο χρόνο εκτέλεσης Dovo και μια υπάρχουσα σύζευξη. Το SSH από μόνο του δεν παρέχει πρόσβαση στο Dovo.',
  'No remote device hosts yet. Local devices remain available.':
    'Δεν υπάρχουν ακόμα απομακρυσμένοι κεντρικοί υπολογιστές συσκευών. Οι τοπικές συσκευές παραμένουν διαθέσιμες.',
  'Add device host': 'Προσθήκη κεντρικού υπολογιστή συσκευής',
  'Default device host': 'Προεπιλεγμένος κεντρικός υπολογιστής συσκευής',
  'Local runtime (no remote default)': 'Τοπικός χρόνος εκτέλεσης (χωρίς απομακρυσμένη προεπιλογή)',
  'Preselects this host in the desktop device picker. The mobile picker shows devices from all reachable hosts.':
    'Προεπιλέγει αυτόν τον κεντρικό υπολογιστή στο εργαλείο επιλογής συσκευών επιφάνειας εργασίας. Το εργαλείο επιλογής για κινητά εμφανίζει συσκευές από όλους τους προσβάσιμους κεντρικούς υπολογιστές.',
  'Remove device host': 'Κατάργηση κεντρικού υπολογιστή συσκευής',
  'Remove device host?': 'Κατάργηση κεντρικού υπολογιστή συσκευής;',
  'This removes the SSH device host configuration from this runtime. The destination pairing and its devices remain intact.':
    'Αυτό καταργεί τη διαμόρφωση κεντρικού υπολογιστή συσκευής SSH από αυτόν τον χρόνο εκτέλεσης. Η σύζευξη προορισμού και οι συσκευές της παραμένουν άθικτες.',
  'Pair a computer to configure its device hosts.':
    'Αντιστοιχίστε έναν υπολογιστή για να διαμορφώσετε τους κεντρικούς υπολογιστές της συσκευής του.',
  'The current runtime connects over SSH to the destination computer. Install an updated Dovo runtime there and pair it with this phone first.':
    'Ο τρέχων χρόνος εκτέλεσης συνδέεται μέσω SSH στον υπολογιστή προορισμού. Εγκαταστήστε εκεί έναν ενημερωμένο χρόνο εκτέλεσης Dovo και πραγματοποιήστε σύζευξη πρώτα με αυτό το τηλέφωνο.',
  'Device host name': 'Όνομα κεντρικού υπολογιστή συσκευής',
  'Paired destination computer': 'Συζευγμένος υπολογιστής προορισμού',
  'Keep saved pairing': 'Συνεχίστε την αποθηκευμένη σύζευξη',
  'Choose a paired computer': 'Επιλέξτε έναν ζευγοποιημένο υπολογιστή',
  'Uses the destination’s saved pairing securely. No pairing token is shown here.':
    'Χρησιμοποιεί με ασφάλεια την αποθηκευμένη σύζευξη του προορισμού. Δεν εμφανίζεται κανένα διακριτικό σύζευξης εδώ.',
  'Destination runtime address': 'Διεύθυνση χρόνου εκτέλεσης προορισμού',
  'HTTP and HTTPS are supported. Use an address reachable from the current runtime. If the address differs from your saved profile, choose the pairing for that same destination.':
    'Υποστηρίζονται HTTP και HTTPS. Χρησιμοποιήστε μια διεύθυνση προσβάσιμη από τον τρέχοντα χρόνο εκτέλεσης. Εάν η διεύθυνση διαφέρει από το αποθηκευμένο προφίλ σας, επιλέξτε τη σύζευξη για τον ίδιο προορισμό.',
  'SSH host': 'Κεντρικός υπολογιστής SSH',
  'mac-mini.local or VPN address': 'διεύθυνση mac-mini.local ή VPN',
  'SSH user': 'Χρήστης SSH',
  'SSH port': 'Θύρα SSH',
  'SSH identity file path (optional)': 'Διαδρομή αρχείου ταυτότητας SSH (προαιρετικό)',
