  'Save device host': 'Αποθήκευση κεντρικού υπολογιστή συσκευής',
  'Cancel editing': 'Ακύρωση επεξεργασίας',
  'Computer updates': 'Ενημερώσεις υπολογιστή',
  'Updates in progress or ready to install': 'Ενημερώσεις σε εξέλιξη ή έτοιμες για εγκατάσταση',
