    'Η σύνδεση επαναφέρει την κοινή χρήση μόλις αποθηκευτεί το κλειδί σας στον λογαριασμό σας. Για παλαιότερη κοινή χρήση, ανοίξτε το Studio σε μια συσκευή όπου λειτουργεί η κοινή χρήση, επαναφέρετε ένα αντίγραφο ασφαλείας ή επαναφέρετε παρακάτω εάν χαθεί το κλειδί.',
  'Retry account recovery': 'Δοκιμάστε ξανά την ανάκτηση λογαριασμού',
  'I no longer have the key': 'Δεν έχω πια το κλειδί',
  'Reset legacy sharing?': 'Επαναφορά κοινής χρήσης παλαιού τύπου;',
  'This deletes all your hosted thread and artifact copies, invitations and links for this account. Local content stays intact. New sharing will recover automatically when you sign in.':
    'Αυτό διαγράφει όλα τα φιλοξενούμενα νήματα και αντίγραφα τεχνουργημάτων, προσκλήσεις και συνδέσμους για αυτόν τον λογαριασμό. Το τοπικό περιεχόμενο παραμένει ανέπαφο. Η νέα κοινή χρήση θα ανακτηθεί αυτόματα όταν συνδεθείτε.',
  'Delete old copies and reset': 'Διαγράψτε τα παλιά αντίγραφα και επαναφέρετε',
  'Sharing is ready with account recovery': 'Η κοινή χρήση είναι έτοιμη με ανάκτηση λογαριασμού',
  'Restore from a backup': 'Επαναφορά από αντίγραφο ασφαλείας',
  'Recovery key': 'Κλειδί ανάκτησης',
  'Restore sharing key': 'Επαναφορά κλειδιού κοινής χρήσης',
  'People with access': 'Άτομα με πρόσβαση',
