  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Αυτό το νήμα παραμένει μόνο για ανάγνωση. Δοκιμάστε ξανά την κίνηση ή ακυρώστε την. Το Cancel ξεκλειδώνει το νήμα μόνο αφού το {value0} επιβεβαιώσει ότι αφαίρεσε το αντίγραφό του. Εάν το {value1} έχει ήδη λάβει το νήμα, η ακύρωση ολοκληρώνει τη μετακίνηση.',
