    'Κάντε προεπισκόπηση μιας περιόδου λειτουργίας από αυτό το έργο στον επιλεγμένο υπολογιστή. Το Dovo δημιουργεί ένα ιδιωτικό αντίγραφο για συνέχεια και αφήνει ανέγγιχτη την πηγή του τερματικού. Τα εργαλεία Pi είναι απενεργοποιημένα εκτός εάν επιλέξετε την πλήρη πρόσβαση. οι επεκτάσεις και το MCP παραμένουν απενεργοποιημένα. Η συνέχεια απαιτεί @earendil-works/pi-coding-agent 1.4 ή νεότερη έκδοση.',
