  'Project on computer overrides Project, then Computer, then shared defaults. Restart and PR settling fall back to computer defaults. Archiving uses the computer inactivity policy when no scoped rule is set.':
    'Το Έργο στον υπολογιστή παρακάμπτει το Έργο, μετά τον Υπολογιστή και μετά τις κοινόχρηστες προεπιλογές. Η επανεκκίνηση και η διευθέτηση PR επανέρχονται στις προεπιλογές του υπολογιστή. Η αρχειοθέτηση χρησιμοποιεί την πολιτική αδράνειας υπολογιστή όταν δεν έχει οριστεί κανόνας εμβέλειας.',
  'Open computer running-task defaults': 'Ανοίξτε τις προεπιλογές εκτέλεσης εργασιών υπολογιστή',
