  'Update this computer’s runtime to configure scoped lifecycle settings.':
    'Ενημερώστε το χρόνο εκτέλεσης αυτού του υπολογιστή για να διαμορφώσετε τις ρυθμίσεις κύκλου ζωής εύρους.',
