  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Ρυθμίστε το CuaDriver σε αυτόν τον κεντρικό υπολογιστή χρόνου εκτέλεσης. Το CuaDriver κατέχει δικαιώματα λειτουργικού συστήματος. Η Dovo συνδέει πράκτορες μέσω MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Φιλοξενήστε εκτελέσιμα ονόματα ή διαδρομές, χωρίς παράθεση κελύφους. Οι παρακάμψεις αντιπροσώπων έχουν προτεραιότητα. Τα νέα τερματικά χρησιμοποιούν αυτές τις ρυθμίσεις κελύφους.',
