    'Αυτόματο κέλυφος: {value0}. Προεπιλογή: -l (κέλυφος σύνδεσης).',
  'Enable agent computer use on this computer':
    'Ενεργοποιήστε τη χρήση υπολογιστή αντιπροσώπου σε αυτόν τον υπολογιστή',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Παραχωρεί σε εγγράψιμους πράκτορες πρόσβαση στην επιφάνεια εργασίας αυτού του υπολογιστή. Οι πράκτορες μόνο για ανάγνωση εξαιρούνται. Ο χρήστης και οι πράκτορες μοιράζονται την κατάσταση της επιφάνειας εργασίας και της εφαρμογής.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Αφήστε το πρόγραμμα οδήγησης Cua κενό για να το εντοπίσετε στη PATH αυτού του υπολογιστή ή στον τυπικό φάκελο εγκατάστασης. Οι αλλαγές ισχύουν για νέες στροφές αντιπροσώπων.',
  '1. Install on this computer': '1. Εγκαταστήστε σε αυτόν τον υπολογιστή',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Εκτελέστε το επίσημο πρόγραμμα εγκατάστασης στον κεντρικό υπολογιστή χρόνου εκτέλεσης και, στη συνέχεια, ανανεώστε την κατάσταση. Κατεβάζει και εγκαθιστά το CuaDriver. δεν απαιτείται λογαριασμός Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Τα ελάχιστα συστήματα Linux χρειάζονται libxi6 και at-spi2-core. Το GNOME χρειάζεται τον βοηθό WinRects της Cua. δείτε τον οδηγό εγκατάστασης.',
  'Install and set up Cua Driver': 'Εγκαταστήστε και ρυθμίστε το πρόγραμμα οδήγησης Cua',
  'Detect / check Cua Driver': 'Ανίχνευση / έλεγχος προγράμματος οδήγησης Cua',
  '2. Permissions & desktop access': '2. Δικαιώματα & πρόσβαση στην επιφάνεια εργασίας',
  '3. Agent MCP, skills & hooks': '3. Agent MCP, skills & hooks',
  '4. Computer History (optional preview)': '4. Ιστορικό υπολογιστή (προαιρετική προεπισκόπηση)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Παραχωρήστε στο macOS Accessibility and Screen Recording στο CuaDriver και αποδεχτείτε την επανεκκίνηση του. Δοκιμή πρόσβασης στην επιφάνεια εργασίας λίστες εφαρμογών χωρίς να τις αλλάξετε. Τα στοιχεία ελέγχου Daemon επηρεάζουν τις ενεργές συνεδρίες χρήσης υπολογιστή.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Αποθηκεύστε το διακόπτη χρήσης υπολογιστή για αυτόματη dovo_cua MCP σε νέες εγγράψιμες στροφές. Δεν απαιτείται μη αυτόματη εγγραφή MCP. Εγκαταστήστε το προαιρετικό επίσημο πακέτο δεξιοτήτων. συνδέσεις εγκατάστασης που εντόπισαν πράκτορες σε αυτόν τον υπολογιστή.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Ιστορικό συμμετοχής, κρυπτογραφημένο, μόνο για μεταδεδομένα. Η ενεργοποίηση μπορεί να επανεκκινήσει τον δαίμονα. Απενεργοποίηση διατηρεί καταγεγραμμένα δεδομένα. η παύση διακόπτει προσωρινά την εγγραφή. Μη υποστηριζόμενες εκδόσεις αναφέρουν σφάλμα. Τα δεδομένα παραμένουν στον κεντρικό υπολογιστή χρόνου εκτέλεσης. Δείτε το πρόσφατο ιστορικό ανάκτησης έως και 20 συμβάντων εδώ.',
  'Delete recorded Computer History?': 'Διαγραφή εγγεγραμμένου ιστορικού υπολογιστή;',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Διαγράψτε όλο το καταγεγραμμένο ιστορικό και το κλειδί κρυπτογράφησης σε αυτόν τον υπολογιστή. Αυτό δεν μπορεί να αναιρεθεί.',
