  'This computer connection changed. Choose where to create this work again.':
    'Αυτή η σύνδεση υπολογιστή άλλαξε. Επιλέξτε πού θα δημιουργήσετε ξανά αυτό το έργο.',
  'Choose another computer': 'Επιλέξτε άλλον υπολογιστή',
  'Choose where this work should run.': 'Επιλέξτε πού θα εκτελείται αυτή η εργασία.',
  'Shows connection details': 'Εμφανίζει λεπτομέρειες σύνδεσης',
  'Reconnects. Touch and hold for details': 'Επανασυνδέεται. Αγγίξτε παρατεταμένα για λεπτομέρειες',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Αυτό το τηλέφωνο δεν είναι πλέον ζευγοποιημένο με υπολογιστή παρακάτω. Καταργήθηκε σε αυτόν τον υπολογιστή ή έγινε επαναφορά του χρόνου εκτέλεσης. Αντιστοιχίστε το ξανά από τις Συσκευές στις Ρυθμίσεις.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Συνδέθηκε χρησιμοποιώντας ενημερώσεις HTTP. Η ζωντανή ροή επανασυνδέεται ή δεν είναι διαθέσιμη. Επανασυνδεθείτε για να το δοκιμάσετε ξανά.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Η αποθηκευμένη εργασία παραμένει διαθέσιμη. Συνδέστε ξανά έναν υπολογιστή για να στείλετε μηνύματα ή να εκτελέσετε εντολές εκεί.',
  '{value0} · {value1} saved actions': '{value0} · {value1} αποθηκευμένες ενέργειες',
  'Thread: {value0}': 'Θέμα: {value0}',
  'Computer access changed. This action may already have run.':
    'Η πρόσβαση στον υπολογιστή άλλαξε. Αυτή η ενέργεια μπορεί να έχει ήδη εκτελεστεί.',
  'Retry action': 'Δοκιμάστε ξανά την ενέργεια',
  'Retry this action?': 'Επανάληψη αυτής της ενέργειας;',
  'Computer access changed. This action may already have run; retrying could repeat it. Check the computer before continuing.':
    'Η πρόσβαση στον υπολογιστή άλλαξε. Αυτή η ενέργεια μπορεί να έχει ήδη εκτελεστεί. η επανάληψη θα μπορούσε να το επαναλάβει. Ελέγξτε τον υπολογιστή πριν συνεχίσετε.',
  'Discard action': 'Απόρριψη ενέργειας',
  'Discard this action?': 'Απόρριψη αυτής της ενέργειας;',
  'Unsent work will be removed from this phone. Actions already applied on the computer remain applied.':
    'Η μη απεσταλμένη εργασία θα καταργηθεί από αυτό το τηλέφωνο. Οι ενέργειες που έχουν ήδη εφαρμοστεί στον υπολογιστή εξακολουθούν να εφαρμόζονται.',
  'Retry saved actions': 'Δοκιμάστε ξανά αποθηκευμένες ενέργειες',
  'Retry saved actions on {value0}?': 'Επανάληψη αποθηκευμένων ενεργειών στο {value0};',
  'Access to this computer was renewed. Some saved actions may already have run and retrying could repeat them. Check the computer before continuing. Messages keep their original delivery identity.':
    'Η πρόσβαση σε αυτόν τον υπολογιστή ανανεώθηκε. Ορισμένες αποθηκευμένες ενέργειες μπορεί να έχουν ήδη εκτελεστεί και η επανάληψη θα μπορούσε να τις επαναλάβει. Ελέγξτε τον υπολογιστή πριν συνεχίσετε. Τα μηνύματα διατηρούν την αρχική τους ταυτότητα παράδοσης.',
  'Discard saved actions': 'Απόρριψη αποθηκευμένων ενεργειών',
  'Discard saved actions?': 'Απόρριψη αποθηκευμένων ενεργειών;',
  'Actions already applied on the computer will remain applied. Unsent actions will be removed from this phone.':
    'Οι ενέργειες που έχουν ήδη εφαρμοστεί στον υπολογιστή θα εξακολουθήσουν να εφαρμόζονται. Οι μη απεσταλμένες ενέργειες θα καταργηθούν από αυτό το τηλέφωνο.',
  'Saved attachment': 'Αποθηκευμένο συνημμένο',
  'Attach to the task’s current draft or discard the upload. Existing files remain unchanged.':
    'Επισυνάψτε στο τρέχον πρόχειρο της εργασίας ή απορρίψτε τη μεταφόρτωση. Τα υπάρχοντα αρχεία παραμένουν αμετάβλητα.',
  'Attach to current task draft': 'Επισύναψη στο τρέχον προσχέδιο εργασίας',
  'Attach saved file?': 'Επισύναψη αποθηκευμένου αρχείου;',
  'This adds the saved file to the current draft of its original task. It does not modify a queued message.':
    'Αυτό προσθέτει το αποθηκευμένο αρχείο στο τρέχον προσχέδιο της αρχικής του εργασίας. Δεν τροποποιεί ένα μήνυμα στην ουρά.',
