  'Discard saved upload': 'Απόρριψη αποθηκευμένης μεταφόρτωσης',
  'Discard saved upload?': 'Απόρριψη αποθηκευμένης μεταφόρτωσης;',
  'This permanently abandons this upload. An attachment already saved in a message or draft is not removed.':
    'Αυτό εγκαταλείπει οριστικά αυτήν τη μεταφόρτωση. Ένα συνημμένο που έχει ήδη αποθηκευτεί σε μήνυμα ή πρόχειρο δεν καταργείται.',
  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Ζεύγος ξανά',
  'Connection stages': 'Στάδια σύνδεσης',
  'Start your computer': 'Ξεκινήστε τον υπολογιστή σας',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Ανοίξτε το Dovo στον υπολογιστή σας και κρατήστε τον ξύπνιο. Στις Ρυθμίσεις → Συσκευές και χρόνος εκτέλεσης, συνδεθείτε και ενεργοποιήστε το Dovo Connect. Συνδεθείτε στον ίδιο λογαριασμό στο τηλέφωνό σας και επιλέξτε Σύνδεση. Δεν απαιτείται κωδικός σύζευξης, VPN ή τοπική IP για πρόσβαση στο Διαδίκτυο.',
  'Direct internet connection': 'Άμεση σύνδεση στο διαδίκτυο',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'Το WebRTC + STUN συνδέει το τηλέφωνό σας απευθείας στον υπολογιστή. Το περιεχόμενό σας είναι κρυπτογραφημένο από άκρο σε άκρο. Η ενεργοποίηση του Dovo Connect επιτρέπει την επαναφορά κρυπτογραφημένων αναμετάδοσης, εάν ένα δίκτυο αποκλείει τις άμεσες συνδέσεις. Το ρελέ προωθεί κρυπτογραφημένη κίνηση. δεν μπορεί να διαβάσει το περιεχόμενό σας.',
  'LAN / VPN connections': 'Συνδέσεις LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Συνδυάστε LAN / VPN ξεχωριστά για να προτιμάτε αυτήν τη σύνδεση όταν είναι διαθέσιμη. Αντιγράψτε την πλήρη διεύθυνση Wi-Fi, Tailscale, NetBird ή HTTPS που εμφανίζεται στον υπολογιστή σας, συμπεριλαμβανομένης της θύρας του. Το localhost και το 0.0.0.0 δεν είναι διευθύνσεις στις οποίες μπορεί να συνδεθεί το τηλέφωνό σας.',
  'Check your network': 'Ελέγξτε το δίκτυό σας',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Χρησιμοποιήστε το ίδιο Wi-Fi ή συνδέστε και τις δύο συσκευές στο VPN σας. Για συνδέσεις Wi-Fi, επιτρέψτε στο Dovo πρόσβαση στο Τοπικό σας δίκτυο στις Ρυθμίσεις iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Οι κωδικοί σύζευξης λήγουν μετά από δύο λεπτά. Οι κωδικοί CLI εγκρίνονται αυτόματα. ένας κωδικός από την επιφάνεια εργασίας μπορεί να χρειάζεται έγκριση εκεί.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Η σύζευξή σας έχει αποθηκευτεί. Δοκιμάστε να επανασυνδεθείτε πριν δημιουργήσετε άλλον κωδικό. Εάν η διεύθυνση άλλαξε, επιλέξτε Ενημέρωση διεύθυνσης σύνδεσης στις ρυθμίσεις αυτού του υπολογιστή.',
  'Dovo Connect for {value0}': 'Dovo Connect για {value0}',
  'Dovo Connect + relay': 'Dovo Connect + ρελέ',
  'Connect server: {value0}': 'Διακομιστής σύνδεσης: {value0}',
