  'Use the same account as your computer for Dovo Connect. No pairing code needed. LAN / VPN pairing is separate and takes priority when available.':
    'Χρησιμοποιήστε τον ίδιο λογαριασμό με τον υπολογιστή σας για το Dovo Connect. Δεν απαιτείται κωδικός σύζευξης. Η σύζευξη LAN / VPN είναι ξεχωριστή και έχει προτεραιότητα όταν είναι διαθέσιμη.',
  'Retry account deletion': 'Δοκιμάστε ξανά τη διαγραφή λογαριασμού',
