  'Delete account': 'Διαγραφή λογαριασμού',
  'Delete your Dovo account?': 'Διαγραφή του λογαριασμού σας στο Dovo;',
  'This permanently deletes your hosted identity, linked computers and notification permissions on all devices. Files, threads and separate pairings on your computers remain. Service backups expire within 14 days. This cannot be undone.':
    'Αυτό διαγράφει οριστικά την ταυτότητα που φιλοξενείται, τους συνδεδεμένους υπολογιστές και τα δικαιώματα ειδοποιήσεων σε όλες τις συσκευές. Τα αρχεία, τα νήματα και οι ξεχωριστές ζεύξεις στους υπολογιστές σας παραμένουν. Τα αντίγραφα ασφαλείας της υπηρεσίας λήγουν εντός 14 ημερών. Αυτό δεν μπορεί να αναιρεθεί.',
