  'Memory limit (MB)': 'Όριο μνήμης (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Εκτελεί τον πράκτορα κάθε νέας συνομιλίας, τις εντολές του και τα τερματικά του σε ένα τοπικό κοντέινερ Docker ή Podman. Προσαρτώνται μόνο το αντίγραφο εργασίας και η σύνδεση του επιλεγμένου πράκτορα. Οι συνομιλίες που εκτελούνται κρατούν τη ρύθμισή τους.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Χωρίς πρόσβαση στο δίκτυο, ο πράκτορας δεν μπορεί να φτάσει στο API του μοντέλου του, εκτός αν αυτό το API εκτελείται μέσα στο sandbox. Οι εγκαταστάσεις πακέτων και τα αιτήματα web επίσης αποτυγχάνουν.',
