    'Ο πράκτορας εκτελείται σε αυτόν τον υπολογιστή με τον λογαριασμό χρήστη σας.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Ο πράκτορας, οι εντολές του και τα τερματικά του εκτελούνται σε ένα κοντέινερ. Προσαρτώνται μόνο αυτό το αντίγραφο εργασίας και η σύνδεση του πράκτορα.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Κρατά σε αναμονή νέα εργασία που εκτελείται χωρίς μήνυμά σας μόλις το εκτιμώμενο κόστος της φτάσει το όριο. Ισχύει για συνέχειες Bot, βήματα ρουτίνας ενός Bot, προγραμματισμένα μηνύματα και θυγατρικούς πράκτορες. Κάθε νήμα ή Bot μετρά μαζί με τους θυγατρικούς πράκτορές του. Μια ρουτίνα χωρίς Bot ξεκινά νέα μέτρηση σε κάθε εκτέλεση. Ορίστε τα δικά της όρια στην ενότητα Παρακολούθηση και όρια. Το επόμενο μήνυμά σας ή η Συνέχεια μηδενίζει τη μέτρηση. Οι γύροι χωρίς τιμή κρατούν επίσης εργασία σε αναμονή. Ένας γύρος που εκτελείται ολοκληρώνεται πάντα.',
  'During your request: "{value0}"': 'Κατά το αίτημά σου: "{value0}"',
